import sys

def main():
    try:
        line = sys.stdin.read().strip()
        if not line:
            return
        n = int(line)
    except ValueError:
        return

    adj = [[0] * n for _ in range(n)]

    if n % 2 == 1:
        base = 1
        step = 2
        current = base
        for dist in range(1, (n + 1) // 2):
            val = current
            current += step
            for i in range(n):
                j = (i + dist) % n
                adj[i][j] = val
                adj[j][i] = val
    else:
        base = 1
        step = 2
        for dist in range(1, n // 2):
            val = base
            base += step
            for i in range(n):
                j = (dist + i) % n
                adj[i][j] = val
                adj[i][j] = val
        mid = base
        for i in range(n):
            j = (i + n // 2) % n
            if i < j:
                adj[i][j] = mid
                adj[j][i] = mid
            mid += step

    for row in adj:
        print(*(row))

if __name__ == "__main__":
    main()
